SELECT id, tenant_id, user_id, user_name, login_time, ip_address, status, message
FROM login_log

    tenant_id = #{tenantId}

        AND user_name LIKE CONCAT('%', #{userName}, '%')


        AND status = #{status}


ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM login_log

    tenant_id = #{tenantId}

        AND user_name LIKE CONCAT('%', #{userName}, '%')


        AND status = #{status}

SELECT COUNT(1)
FROM login_log
WHERE tenant_id = #{tenantId}
